&lt;ol class=&quot;ak-ol&quot; data-local-id=&quot;2991e526&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;orderedList&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
&lt;li data-local-id=&quot;7874be7e&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
